questions.solution:
function loadConfig(env) {
  const apiKey = env.TASKS_API_KEY;
  if (!apiKey) {
    throw new Error("TASKS_API_KEY is not set");
  }
  const port = Number(env.PORT ?? 3000);
  return { port, apiKey };
}

try {
  loadConfig({ PORT: "4000" });
} catch (error) {
  console.log(error.message);
}
const config = loadConfig({ PORT: "4000", TASKS_API_KEY: "s3cret-value" });
console.log(`Port: ${config.port}, key has ${config.apiKey.length} characters`);

