function toExample(envText) {
  return envText
    .split("\n")
    .filter((line) => line.trim() !== "")
    .map((line) => line.split("=")[0] + "=")
    .join("\n");
}

const envText = "PORT=4000\nTASKS_API_KEY=be4a80c451f09e6e\n";
console.log(toExample(envText));
